begin;
create extension if not exists pgtap with schema extensions;
select plan(17);
select ok(not has_function_privilege('anon','public.workcraft_prepare_auth_email(text)','EXECUTE'),'anonymous cannot reserve Auth mail');
select ok(not has_function_privilege('authenticated','public.workcraft_upgrade_share_secret(uuid,text,text)','EXECUTE'),'browser cannot replace encrypted secrets');
select ok(not has_function_privilege('anon','public.workcraft_report_snapshot()','EXECUTE'),'reports require authentication');
insert into auth.users(id,email,raw_user_meta_data) values('a9000000-0000-4000-8000-000000000001','launch-owner@example.test','{}'),('a9000000-0000-4000-8000-000000000002','launch-other@example.test','{}');
insert into public.subscriptions(user_id,status) values('a9000000-0000-4000-8000-000000000001','active');
insert into public.estimates(id,user_id,client_name,client_email,tax_rate) values('b9000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000001','Fixture','customer@example.test',7.5);
insert into public.line_items(estimate_id,description,quantity,unit_price) select 'b9000000-0000-4000-8000-000000000001','Item',1,1 from generate_series(1,1001);
update public.estimates set status='accepted' where id='b9000000-0000-4000-8000-000000000001';
insert into public.jobs(id,user_id,estimate_id,title,quoted_total,actual_cost,status) values('c9000000-0000-4000-8000-000000000001','a9000000-0000-4000-8000-000000000001','b9000000-0000-4000-8000-000000000001','Taxed',1076.08,600,'completed');
select is((select quoted_tax_cents from public.jobs where id='c9000000-0000-4000-8000-000000000001'),7508::bigint,'job snapshots exact rounded tax');
update public.jobs set quoted_tax_cents=0 where id='c9000000-0000-4000-8000-000000000001';
select is((select quoted_tax_cents from public.jobs where id='c9000000-0000-4000-8000-000000000001'),7508::bigint,'client-supplied tax snapshot is recomputed');
set local role authenticated;
set local request.jwt.claims='{"sub":"a9000000-0000-4000-8000-000000000001","role":"authenticated"}';
select is((public.workcraft_report_snapshot()->'estimates'->0->>'total_cents')::numeric,107608::numeric,'reports include over 1000 line items without row-cap truncation');
select is((public.workcraft_report_snapshot()->>'revenue_cents')::numeric,100100::numeric,'profit revenue excludes sales tax');
select is((public.workcraft_report_snapshot()->>'cost_cents')::numeric,60000::numeric,'profit includes actual costs');
set local request.jwt.claims='{"sub":"a9000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(jsonb_array_length(public.workcraft_report_snapshot()->'estimates'),0,'other account cannot see report estimates');
select is((public.workcraft_report_snapshot()->>'completed_count')::integer,0,'Free other account has no private job aggregate');
reset role;
set local role service_role;
select lives_ok('select * from public.workcraft_claim_inactivity_notices(1)','inactivity claims need no auth.users SELECT');
select lives_ok('select * from public.workcraft_claim_due_account_deletions(1)','due-deletion claims need no auth.users SELECT');
select lives_ok('select * from public.workcraft_claim_failed_account_deletions(1)','retry claims need no auth.users SELECT');
select is((public.workcraft_prepare_auth_email('auth-'||repeat('a',64))->>'allowed')::boolean,true,'signed Auth admission is reserved');
select is((public.workcraft_prepare_auth_email('auth-'||repeat('a',64))->>'allowed')::boolean,false,'duplicate Auth request cannot overlap lease');
update public.notification_outbox set lease_until=now()-interval '1 second' where send_key='auth-'||repeat('a',64);
select is((select count(*) from public.workcraft_claim_notifications(20,null) where source='auth'),0::bigint,'generic cron never sends uncommitted Auth tokens');
select is((public.workcraft_prepare_auth_email('auth-'||repeat('a',64))->>'allowed')::boolean,true,'explicit signed retry reuses admission after lease expiry');
select * from finish();
rollback;
